function slackSignatureInput(headers, raw, nowSeconds) {
  const timestamp = headers?.["x-slack-request-timestamp"];
  const signature = headers?.["x-slack-signature"];
  if (
    typeof timestamp !== "string" ||
    !/^\d{10}$/.test(timestamp) ||
    Math.abs(nowSeconds - Number(timestamp)) > 300 ||
    typeof signature !== "string" ||
    !/^v0=[a-f0-9]{64}$/.test(signature) ||
    typeof raw !== "string" ||
    !/^[\x20-\x7e]{1,16384}$/.test(raw) ||
    !/^application\/x-www-form-urlencoded(?:\s*;|$)/i.test(headers?.["content-type"] ?? "")
  ) {
    return { ready: false, base: "v0:invalid", signature: "" };
  }
  return {
    ready: true,
    base: "v0:" + timestamp + ":" + raw,
    signature,
    raw,
    retry: /^\d+$/.test(headers["x-slack-retry-num"] ?? ""),
  };
}

let raw = "";
try {
  const bytes = await helpers.getBinaryDataBuffer(0, "data");
  if (bytes.length <= 16384 && !bytes.some((byte) => byte < 32 || byte > 126))
    raw = Buffer.from(bytes).toString("ascii");
} catch {}
return { json: slackSignatureInput($json.headers, raw, Math.floor(Date.now() / 1000)) };

function equalSignature(received, digest) {
  if (
    typeof digest !== "string" ||
    !/^[a-f0-9]{64}$/.test(digest) ||
    typeof received !== "string" ||
    received.length !== 67
  )
    return false;
  const expected = "v0=" + digest;
  let difference = 0;
  for (let i = 0; i < expected.length; i++)
    difference |= received.charCodeAt(i) ^ expected.charCodeAt(i);
  return difference === 0;
}

function parseSlackForm(raw) {
  const decoded = Object.create(null);
  const unescape = (value) => decodeURIComponent(value.replaceAll("+", " "));
  for (const pair of raw.split("&")) {
    const separator = pair.indexOf("=");
    if (separator < 0) throw new Error("Malformed Slack command.");
    const key = unescape(pair.slice(0, separator));
    if (!key || Object.hasOwn(decoded, key)) throw new Error("Repeated Slack command field.");
    decoded[key] = unescape(pair.slice(separator + 1));
  }
  return decoded;
}

function admitMeet(prepared, digest, workspaceId) {
  if (!prepared.ready || !equalSignature(prepared.signature, digest)) {
    return { accepted: false, status: 401, response: { error: "Invalid Slack signature." } };
  }
  let form;
  try {
    form = parseSlackForm(prepared.raw);
  } catch {
    return { accepted: false, status: 400, response: { error: "Invalid Slack command." } };
  }
  if (form.command !== "/meet" || !/^[CGD][A-Z0-9]{3,}$/.test(form.channel_id ?? "")) {
    return {
      accepted: false,
      status: 400,
      response: { error: "Expected /meet in a Slack conversation." },
    };
  }
  if (!/^T[A-Z0-9]{3,}$/.test(workspaceId) || form.team_id !== workspaceId) {
    return {
      accepted: false,
      status: 403,
      response: { error: "This Slack workspace is not configured." },
    };
  }
  if (prepared.retry)
    return {
      accepted: false,
      status: 200,
      response: { response_type: "ephemeral", text: "This command has already been received." },
    };
  return { accepted: true, channel: form.channel_id };
}
const workspaceId = "YOUR_SLACK_WORKSPACE_ID";
return {
  json: admitMeet($("Read the signed request bytes").first().json, $json.digest, workspaceId),
};

function slackMessage(channel, status, space) {
  if (
    (status !== 200 && status !== 201) ||
    typeof space?.meetingUri !== "string" ||
    !/^https:\/\/meet\.google\.com\/[a-z]+-[a-z]+-[a-z]+$/.test(space.meetingUri)
  ) {
    throw new Error("Google Meet did not return a confirmed join link. No link was posted.");
  }
  return {
    channel,
    text: "Join me here: " + space.meetingUri,
    unfurl_links: false,
    unfurl_media: false,
    allowed_mentions: { parse: [] },
  };
}
return {
  json: slackMessage(
    $("Verify Slack and select the conversation").first().json.channel,
    $json.statusCode,
    $json.body,
  ),
};

const channel = $("Verify Slack and select the conversation").first().json.channel;
const { statusCode, body } = $json;
if (
  statusCode !== 200 ||
  body?.ok !== true ||
  body.channel !== channel ||
  typeof body.ts !== "string" ||
  !body.ts
) {
  throw new Error(
    "Slack did not confirm the message. Check the conversation before running the command again.",
  );
}
return { json: { channel, messageTimestamp: body.ts } };
